// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz parameters: an address to act as 'from' (fuzzer-supplied), a non-empty array length,
    // and a boolean that decides whether the helper should revert on calls.
    function testFuzz_property(address from, uint8 tosLen, bool calleeReverts) public {
        // keep tosLen in a reasonable range but allow 1..10 so fuzz can find small non-zero lengths
        uint8 len = tosLen % 10; // now 0..9
        vm.assume(len != 0); // require non-empty array as contract requires

        // build the tos array
        address[] memory tos = new address[](len);
        // deploy a helper that either reverts or records the call depending on calleeReverts
        RevertOrRecord helper = new RevertOrRecord(calleeReverts);
        // fill all entries with the helper's address so at least one call will hit a reverting callee when requested
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
        }

        uint256 v = 1; // value parameter; fuzz not strictly needed for this difference

        // Call c.transfer and observe whether it reverts or not.
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): If the helper is set to revert on calls, the reference contract
        // always bubbles up that failure and thus transfer must revert (ok == false). The mutant would
        // instead return true (ok == true) for some inputs. We assert the correct behavior here.
        if (calleeReverts) {
            // when helper is configured to revert, correct contract must not return successfully
            assertTrue(!ok);
        } else {
            // when helper does not revert, both versions should succeed; assert success to keep property universal
            assertTrue(ok);
        }
    }
}

// Helper contract that either reverts on the expected selector or records calls
contract RevertOrRecord {
    bool public shouldRevert;
    // records last received parameters when not reverting
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public calls;

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // The C contract calls with selector of transferFrom(address,address,uint256)
    // Provide that exact function so ABI decoding happens and we can choose to revert.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) {
            revert("revert from helper");
        }
        // record what was received
        lastFrom = from;
        lastTo = to;
        lastV = v;
        calls += 1;
        return true;
    }
}
